edits.newText:
const noteGroups = data.chains
  .map((chain) => ({
    product: chain.product,
    version: chain.version,
    steps: chain.steps
      .filter((step) => step.note)
      .map((step) => ({
        title: `第 ${step.no} 步 · ${step.screen}`,
        description: step.note,
      })),
  }))
  .filter((group) => group.steps.length > 0)

{noteGroups.length > 0 && (
  <Group title="步骤备注">
    {noteGroups.map((group) => (
      <div key={group.product} className="space-y-6">
        <Text>{`${group.product} · ${group.version}`}</Text>
        <List items={group.steps} />
      </div>
    ))}
  </Group>
)}
